1	// JSON Pointer (RFC 6901) and JSON Patch (RFC 6902).
2	
3	export class PatchError extends Error {
4	  constructor(message, index) {
5	    super(message);
6	    this.index = index;
7	  }
8	}
9	Object.defineProperty(PatchError.prototype, 'name', {
10	  value: 'PatchError',
11	  writable: true,
12	  configurable: true,
13	});
14	
15	const OPS = new Set(['add', 'remove', 'replace', 'move', 'copy', 'test']);
16	const INDEX_RE = /^(?:0|[1-9][0-9]*)$/;
17	
18	export function parsePointer(pointer) {
19	  if (typeof pointer !== 'string') throw new TypeError('pointer must be a string');
20	  if (pointer === '') return [];
21	  if (pointer[0] !== '/' || /~(?![01])/.test(pointer)) throw new SyntaxError('invalid pointer');
22	  return pointer
23	    .slice(1)
24	    .split('/')
25	    .map((token) => token.replace(/~([01])/g, (_, c) => (c === '0' ? '~' : '/')));
26	}
27	
28	function isObject(value) {
29	  return value !== null && typeof value === 'object' && !Array.isArray(value);
30	}
31	
32	// Defines an own data member without triggering setters such as __proto__.
33	function setMember(obj, name, value) {
34	  Object.defineProperty(obj, name, { value, writable: true, enumerable: true, configurable: true });
35	}
36	
37	function clone(value) {
38	  if (Array.isArray(value)) return value.map(clone);
39	  if (isObject(value)) {
40	    const copy = {};
41	    for (const name of Object.keys(value)) setMember(copy, name, clone(value[name]));
42	    return copy;
43	  }
44	  return value;
45	}
46	
47	function equal(a, b) {
48	  if (Array.isArray(a)) {
49	    return Array.isArray(b) && a.length === b.length && a.every((item, i) => equal(item, b[i]));
50	  }
51	  if (isObject(a)) {
52	    if (!isObject(b)) return false;
53	    const names = Object.keys(a);
54	    return (
55	      names.length === Object.keys(b).length &&
56	      names.every((name) => Object.hasOwn(b, name) && equal(a[name], b[name]))
57	    );
58	  }
59	  return a === b;
60	}
61	
62	function isProperPrefix(prefix, tokens) {
63	  return prefix.length < tokens.length && prefix.every((token, i) => token === tokens[i]);
64	}
65	
66	// Returns the reason the operation breaks the form rules, or null.
67	function formError(op) {
68	  if (op === null || typeof op !== 'object' || Array.isArray(op)) return 'not an object';
69	  if (!Object.hasOwn(op, 'op') || !OPS.has(op.op)) return 'bad op';
70	  const path = pointerTokens(op, 'path');
71	  if (!path) return 'bad path';
72	  let from = null;
73	  if (op.op === 'move' || op.op === 'copy') {
74	    from = pointerTokens(op, 'from');
75	    if (!from) return 'bad from';
76	  }
77	  if ((op.op === 'add' || op.op === 'replace' || op.op === 'test') && !Object.hasOwn(op, 'value')) {
78	    return 'missing value';
79	  }
80	  if (op.op === 'remove' && path.length === 0) return 'cannot remove root';
81	  if (op.op === 'move' && isProperPrefix(from, path)) return 'cannot move into own child';
82	  return null;
83	}
84	
85	function pointerTokens(op, member) {
86	  if (!Object.hasOwn(op, member) || typeof op[member] !== 'string') return null;
87	  try {
88	    return parsePointer(op[member]);
89	  } catch {
90	    return null;
91	  }
92	}
93	
94	class OpFailure extends Error {}
95	
96	// Returns the value the token names in container, or throws OpFailure.
97	function child(container, token, notFound) {
98	  if (Array.isArray(container)) {
99	    if (token === '-') throw new OpFailure(notFound);
100	    if (!INDEX_RE.test(token)) throw new OpFailure('bad index');
101	    if (Number(token) >= container.length) throw new OpFailure(notFound);
102	    return container[Number(token)];
103	  }
104	  if (isObject(container) && Object.hasOwn(container, token)) return container[token];
105	  throw new OpFailure(notFound);
106	}
107	
108	function follow(doc, tokens, notFound) {
109	  let value = doc;
110	  for (const token of tokens) value = child(value, token, notFound);
111	  return value;
112	}
113	
114	class Document {
115	  constructor(root) {
116	    this.root = root;
117	  }
118	
119	  get(tokens, notFound) {
120	    return follow(this.root, tokens, notFound);
121	  }
122	
123	  add(tokens, value) {
124	    if (tokens.length === 0) {
125	      this.root = value;
126	      return;
127	    }
128	    const parent = follow(this.root, tokens.slice(0, -1), 'path not found');
129	    const last = tokens[tokens.length - 1];
130	    if (Array.isArray(parent)) {
131	      if (last === '-') {
132	        parent.push(value);
133	        return;
134	      }
135	      if (!INDEX_RE.test(last)) throw new OpFailure('bad index');
136	      const index = Number(last);
137	      if (index > parent.length) throw new OpFailure('path not found');
138	      parent.splice(index, 0, value);
139	    } else if (isObject(parent)) {
140	      setMember(parent, last, value);
141	    } else {
142	      throw new OpFailure('path not found');
143	    }
144	  }
145	
146	  // Removes and returns the value tokens name; tokens is never empty.
147	  remove(tokens, notFound) {
148	    const parent = follow(this.root, tokens.slice(0, -1), notFound);
149	    const last = tokens[tokens.length - 1];
150	    const value = child(parent, last, notFound);
151	    if (Array.isArray(parent)) parent.splice(Number(last), 1);
152	    else delete parent[last];
153	    return value;
154	  }
155	
156	  replace(tokens, value) {
157	    if (tokens.length === 0) {
158	      this.root = value;
159	      return;
160	    }
161	    const parent = follow(this.root, tokens.slice(0, -1), 'path not found');
162	    const last = tokens[tokens.length - 1];
163	    child(parent, last, 'path not found');
164	    setMember(parent, Array.isArray(parent) ? Number(last) : last, value);
165	  }
166	}
167	
168	function applyOperation(doc, op) {
169	  const path = parsePointer(op.path);
170	  switch (op.op) {
171	    case 'add':
172	      doc.add(path, clone(op.value));
173	      break;
174	    case 'remove':
175	      doc.remove(path, 'path not found');
176	      break;
177	    case 'replace':
178	      doc.replace(path, clone(op.value));
179	      break;
180	    case 'move': {
181	      const from = parsePointer(op.from);
182	      // Pointer encoding is unique, so equal strings mean equal tokens.
183	      if (op.from === op.path) {
184	        doc.get(from, 'from not found');
185	        break;
186	      }
187	      doc.add(path, doc.remove(from, 'from not found'));
188	      break;
189	    }
190	    case 'copy':
191	      doc.add(path, clone(doc.get(parsePointer(op.from), 'from not found')));
192	      break;
193	    case 'test':
194	      if (!equal(doc.get(path, 'path not found'), op.value)) throw new OpFailure('test failed');
195	      break;
196	  }
197	}
198	
199	export function applyPatch(doc, patch) {
200	  if (!Array.isArray(patch)) throw new PatchError('patch must be an array', null);
201	  const ops = [];
202	  for (let i = 0; i < patch.length; i++) {
203	    const op = Object.hasOwn(patch, i) ? patch[i] : undefined;
204	    const reason = formError(op);
205	    if (reason) throw new PatchError(`operation ${i}: ${reason}`, i);
206	    ops.push(op);
207	  }
208	  const working = new Document(clone(doc));
209	  ops.forEach((op, i) => {
210	    try {
211	      applyOperation(working, op);
212	    } catch (err) {
213	      if (err instanceof OpFailure) throw new PatchError(`operation ${i}: ${err.message}`, i);
214	      throw err;
215	    }
216	  });
217	  return working.root;
218	}
